package sessionflow

import (
	"context"
	"errors"
	"fmt"
	"net/netip"
	"nextzero-cli/model"
	"time"

	"tailscale.com/ipn"
	"tailscale.com/ipn/ipnstate"
	"tailscale.com/types/key"
	"tailscale.com/types/preftype"
)

var ErrMissingLoginCredentials = errors.New("missing server or auth-key")

// errNodeIdentityStatusUnavailable is the single invariant, actionable
// user-facing sentinel for every path where the daemon's node-identity
// status cannot be read. Unknown identity state is never evidence of a
// fresh node: login must fail before any Start or StartLoginInteractive
// mutation instead of guessing enrollment.
var errNodeIdentityStatusUnavailable = errors.New("node identity status unavailable; ensure the NextZero daemon is running and retry")

// nodeIdentityStatusError always renders errNodeIdentityStatusUnavailable
// while keeping the underlying cause reachable through errors.Is/As, so the
// cause stays internal and can never change rendered CLI text.
type nodeIdentityStatusError struct {
	cause error
}

func (e *nodeIdentityStatusError) Error() string {
	return errNodeIdentityStatusUnavailable.Error()
}

func (e *nodeIdentityStatusError) Unwrap() error {
	return e.cause
}

const defaultLoginTimeout = 2 * time.Minute

type ConfigStore interface {
	Load() (*model.Config, error)
	Save(*model.Config) error
}

type LoginNotifyWatcher interface {
	Next() (ipn.Notify, error)
	Close() error
}

type LoginClient interface {
	Start(context.Context, ipn.Options) error
	StartLoginInteractive(context.Context) error
}

type StatusClient interface {
	Status(context.Context) (*ipnstate.Status, error)
}

type LogoutClient interface {
	Logout(context.Context) error
}

type ServiceController interface {
	Restart(service string) error
}

type LoginInput struct {
	Server       string
	AuthKey      string
	Routes       string
	Hostname     string
	ForceReauth  bool
	AcceptRoutes bool
	AcceptDNS    bool
}

type LoginService struct {
	Store       ConfigStore
	Client      LoginClient
	WatchBus    func(context.Context, ipn.NotifyWatchOpt) (LoginNotifyWatcher, error)
	Status      StatusClient
	ParseRoutes func(string) ([]netip.Prefix, error)
	Getenv      func(string) string
}

type LoginResult struct {
	Confirmed bool
}

func NormalizeLoginInput(input LoginInput, getenv func(string) string) (LoginInput, error) {
	if getenv == nil {
		getenv = func(string) string { return "" }
	}
	if input.Server == "" {
		input.Server = getenv("NZ_LOGIN_SERVER")
	}
	if input.AuthKey == "" {
		input.AuthKey = getenv("NZ_AUTHKEY")
	}
	if input.Routes == "" {
		input.Routes = getenv("NZ_ROUTES")
	}
	if input.Hostname == "" {
		input.Hostname = getenv("NZ_HOSTNAME")
	}
	if input.Server == "" || input.AuthKey == "" {
		return input, ErrMissingLoginCredentials
	}
	return input, nil
}

func (s LoginService) Run(ctx context.Context, input LoginInput) (LoginResult, error) {
	cfg, err := s.Store.Load()
	if err != nil {
		return LoginResult{}, fmt.Errorf("load config err :%w", err)
	}

	input, err = NormalizeLoginInput(input, s.Getenv)
	if err != nil {
		return LoginResult{}, err
	}

	advertiseRoutes, err := s.ParseRoutes(input.Routes)
	if err != nil {
		return LoginResult{}, fmt.Errorf("parse routes err: %w", err)
	}

	prefs := ipn.Prefs{
		ControlURL:      input.Server,
		WantRunning:     true,
		RouteAll:        input.AcceptRoutes,
		CorpDNS:         input.AcceptDNS,
		Hostname:        input.Hostname,
		ForceDaemon:     true,
		AdvertiseRoutes: advertiseRoutes,
		NetfilterMode:   preftype.NetfilterOn,
	}

	watchCtx := ctx
	if _, ok := ctx.Deadline(); !ok {
		var cancelTimeout context.CancelFunc
		watchCtx, cancelTimeout = context.WithTimeout(ctx, defaultLoginTimeout)
		defer cancelTimeout()
	}

	watchCtx, cancelWatch := context.WithCancel(watchCtx)
	defer cancelWatch()

	if s.WatchBus == nil {
		return LoginResult{}, errors.New("watch ipn bus not configured")
	}

	watcher, err := s.WatchBus(watchCtx, ipn.NotifyInitialState|ipn.NotifyInitialStatus)
	if err != nil {
		return LoginResult{}, fmt.Errorf("watch ipn bus err: %w", err)
	}
	defer func() {
		_ = watcher.Close()
	}()

	origNodeKey, hasNodeKey, err := s.currentNodeIdentity(ctx)
	if err != nil {
		return LoginResult{}, err
	}

	if err := s.Client.Start(ctx, ipn.Options{AuthKey: input.AuthKey, UpdatePrefs: &prefs}); err != nil {
		return LoginResult{}, fmt.Errorf("login err: %w", err)
	}
	if input.ForceReauth || !hasNodeKey {
		if err := s.Client.StartLoginInteractive(ctx); err != nil {
			return LoginResult{}, fmt.Errorf("initiate login err: %w", err)
		}
	}

	result, err := observeLoginCompletion(watchCtx, watcher, input.ForceReauth, origNodeKey)
	if err != nil {
		return LoginResult{}, err
	}
	if !result.Confirmed {
		return result, nil
	}

	cfg.Routes = input.Routes
	if err := s.Store.Save(cfg); err != nil {
		return LoginResult{}, fmt.Errorf("save config err : %w", err)
	}
	return result, nil
}

// currentNodeIdentity returns the node's current public key together with
// whether the daemon holds a node identity. The identity decision reads the
// profile-derived HaveNodeKey, so it stays correct even before the netmap
// (and therefore Self) is available. When identity state cannot be read it
// returns a nodeIdentityStatusError so callers fail before any auth
// mutation: unknown status is neither a fresh node nor silently enrolled.
func (s LoginService) currentNodeIdentity(ctx context.Context) (key.NodePublic, bool, error) {
	if s.Status == nil {
		return key.NodePublic{}, false, &nodeIdentityStatusError{}
	}
	st, err := s.Status.Status(ctx)
	if err != nil {
		return key.NodePublic{}, false, &nodeIdentityStatusError{cause: err}
	}
	if st == nil {
		return key.NodePublic{}, false, &nodeIdentityStatusError{}
	}
	var nodeKey key.NodePublic
	if st.Self != nil {
		nodeKey = st.Self.PublicKey
	}
	return nodeKey, st.HaveNodeKey, nil
}

func observeLoginCompletion(ctx context.Context, watcher LoginNotifyWatcher, forceReauth bool, origNodeKey key.NodePublic) (LoginResult, error) {
	ipnIsRunning := false
	waitingForKeyChange := forceReauth

	for {
		n, err := watcher.Next()
		if err != nil {
			if ctx.Err() != nil {
				return LoginResult{}, ctx.Err()
			}
			return LoginResult{}, fmt.Errorf("watch ipn bus err: %w", err)
		}
		if n.ErrMessage != nil && *n.ErrMessage != "" {
			return LoginResult{}, fmt.Errorf("login failed: %s", *n.ErrMessage)
		}
		if n.BrowseToURL != nil && *n.BrowseToURL != "" {
			return LoginResult{Confirmed: false}, nil
		}
		if s := n.State; s != nil {
			ipnIsRunning = *s == ipn.Running
			if *s == ipn.NeedsMachineAuth {
				return LoginResult{Confirmed: false}, nil
			}
		}
		if n.SelfChange != nil && n.SelfChange.Key != origNodeKey {
			waitingForKeyChange = false
		}
		if n.LoginFinished != nil && !waitingForKeyChange {
			return LoginResult{Confirmed: true}, nil
		}
		if ipnIsRunning && !waitingForKeyChange {
			return LoginResult{Confirmed: true}, nil
		}
	}
}

type LogoutService struct {
	Store  ConfigStore
	Client LogoutClient
}

func (s LogoutService) Run(ctx context.Context) error {
	cfg, err := s.Store.Load()
	if err != nil {
		return fmt.Errorf("load config err :%w", err)
	}
	if err := s.Client.Logout(ctx); err != nil {
		return fmt.Errorf("logout err : %w", err)
	}
	cfg.Routes = ""
	if err := s.Store.Save(cfg); err != nil {
		return fmt.Errorf("save config err : %w", err)
	}
	return nil
}

type ReloadService struct {
	Controller ServiceController
	Service    string
}

func (s ReloadService) Run() error {
	service := s.Service
	if service == "" {
		service = "nextzero"
	}
	if err := s.Controller.Restart(service); err != nil {
		return fmt.Errorf("restart err: %w", err)
	}
	return nil
}

